package com.attendance;
import java.util.*;import java.time.LocalDate;import java.nio.charset.StandardCharsets;
import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.core.Authentication;import org.springframework.util.LinkedMultiValueMap;import org.springframework.core.io.ByteArrayResource;import org.springframework.web.client.RestClient;
@RestController @RequestMapping("/api") public class Api {
 final JdbcTemplate db; Api(JdbcTemplate db){this.db=db;}
 void check(boolean b,String m){if(!b)throw new ResponseStatusException(HttpStatus.CONFLICT,m);}
 boolean admin(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));}
 void adminOnly(Authentication a){if(!admin(a))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 Map<String,Object> course(UUID id,Authentication a){var c=db.queryForMap("select * from courses where id=?",id);if(!admin(a)&&!c.get("teacher").equals(a.getName()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return c;}
 Map<String,Object> session(UUID id,Authentication a){var s=db.queryForMap("select * from sessions where id=? for update",id);course((UUID)s.get("course_id"),a);return s;}
 void draft(Map<String,Object>s){check(!s.get("status").equals("FINALIZED"),"Session already finalized");}
 void audit(UUID id,Authentication a,String action){db.update("insert into audit(session_id,actor,action) values(?,?,?)",id,a.getName(),action);}
 @GetMapping("/me") Object me(Authentication a){return Map.of("username",a.getName(),"admin",admin(a));}
 @GetMapping("/students") Object students(Authentication a){adminOnly(a);return db.queryForList("select * from students order by roll");}
 record Student(String name,String roll,boolean consent){}
 @PostMapping("/students") Object student(@RequestBody Student x,Authentication a){adminOnly(a);check(x.name()!=null&&!x.name().isBlank()&&x.roll()!=null&&!x.roll().isBlank(),"Name and roll required");UUID id=UUID.randomUUID();db.update("insert into students values(?,?,?,?)",id,x.name(),x.roll(),x.consent());return Map.of("id",id);}
 @GetMapping("/courses") Object courses(Authentication a){return admin(a)?db.queryForList("select * from courses order by name"):db.queryForList("select * from courses where teacher=? order by name",a.getName());}
 record Course(String name,String teacher){}
 @PostMapping("/courses") Object addCourse(@RequestBody Course x,Authentication a){adminOnly(a);check(x.name()!=null&&!x.name().isBlank()&&Set.of("admin","teacher").contains(x.teacher()),"Valid name and teacher required");UUID id=UUID.randomUUID();db.update("insert into courses values(?,?,?)",id,x.name(),x.teacher());return Map.of("id",id);}
 @GetMapping("/courses/{id}/students") Object roster(@PathVariable UUID id,Authentication a){course(id,a);return db.queryForList("select s.* from students s join enrollments e on e.student_id=s.id where e.course_id=? order by roll",id);}
 @PostMapping("/courses/{id}/students/{student}") void enroll(@PathVariable UUID id,@PathVariable UUID student,Authentication a){adminOnly(a);db.update("insert into enrollments values(?,?) on conflict do nothing",id,student);}
 @PostMapping("/students/{id}/faces") Object faces(@PathVariable UUID id,@RequestParam("images") List<MultipartFile> files,Authentication a)throws Exception{adminOnly(a);check(Boolean.TRUE.equals(db.queryForObject("select consent from students where id=?",Boolean.class,id)),"Consent required");check(files.size()>=5&&files.size()<=10,"Upload 5–10 photos");var body=new LinkedMultiValueMap<String,Object>();for(var f:files)body.add("images",resource(f));return ai().post().uri("/enroll/"+id).contentType(MediaType.MULTIPART_FORM_DATA).body(body).retrieve().body(Map.class);}
 @DeleteMapping("/students/{id}/faces") @Transactional void deleteFaces(@PathVariable UUID id,Authentication a){adminOnly(a);ai().delete().uri("/enroll/"+id).retrieve().toBodilessEntity();db.update("update students set consent=false where id=?",id);}
 @GetMapping("/sessions") Object sessions(Authentication a){return admin(a)?db.queryForList("select s.*,c.name from sessions s join courses c on c.id=s.course_id order by class_date desc"):db.queryForList("select s.*,c.name from sessions s join courses c on c.id=s.course_id where c.teacher=? order by class_date desc",a.getName());}
 record NewSession(UUID courseId,LocalDate date){}
 @PostMapping("/sessions") @Transactional Object create(@RequestBody NewSession x,Authentication a){course(x.courseId(),a);check(x.date()!=null,"Date required");UUID id=UUID.randomUUID();db.update("insert into sessions(id,course_id,class_date) values(?,?,?)",id,x.courseId(),x.date());db.update("insert into attendance(session_id,student_id,student_name,roll) select ?,s.id,s.name,s.roll from students s join enrollments e on e.student_id=s.id where e.course_id=?",id,x.courseId());audit(id,a,"CREATED");return Map.of("id",id);}
 @GetMapping("/sessions/{id}") @Transactional Object get(@PathVariable UUID id,Authentication a){var s=session(id,a);return Map.of("session",s,"roster",db.queryForList("select * from attendance where session_id=? order by roll",id),"audit",db.queryForList("select * from audit where session_id=? order by id",id));}
 record Edit(int version,Map<UUID,String> states){}
 @PutMapping("/sessions/{id}") @Transactional Object save(@PathVariable UUID id,@RequestBody Edit x,Authentication a){var s=session(id,a);draft(s);check(((Number)s.get("version")).intValue()==x.version(),"Draft changed. Reload before saving.");for(var e:x.states().entrySet()){check(Set.of("PRESENT","ABSENT","UNCONFIRMED").contains(e.getValue()),"Invalid state");check(db.update("update attendance set state=? where session_id=? and student_id=?",e.getValue(),id,e.getKey())==1,"Student outside roster");}db.update("update sessions set version=version+1,status='IN_REVIEW' where id=?",id);audit(id,a,"DRAFT_SAVED "+x.states());return get(id,a);}
 @PostMapping("/sessions/{id}/confirm") @Transactional Object confirm(@PathVariable UUID id,@RequestBody Map<String,Integer> x,Authentication a){var s=session(id,a);if(s.get("status").equals("FINALIZED"))return get(id,a);check(Objects.equals(s.get("version"),x.get("version")),"Draft changed. Reload.");check(db.queryForObject("select count(*) from attendance where session_id=?",Integer.class,id)>0,"Empty roster");check(db.queryForObject("select count(*) from attendance where session_id=? and state='UNCONFIRMED'",Integer.class,id)==0,"Review every student first");db.update("update sessions set status='FINALIZED',version=version+1 where id=?",id);audit(id,a,"FINALIZED");return get(id,a);}
 @PostMapping("/sessions/{id}/recognize") @Transactional Object recognize(@PathVariable UUID id,@RequestParam("images") List<MultipartFile> files,Authentication a)throws Exception{var s=session(id,a);draft(s);check(files.size()>=1&&files.size()<=3,"Upload 1–3 photos");var ids=db.queryForList("select a.student_id from attendance a join students s on s.id=a.student_id where a.session_id=? and s.consent=true",UUID.class,id);var body=new LinkedMultiValueMap<String,Object>();body.add("studentIds",String.join(",",ids.stream().map(UUID::toString).toList()));for(var f:files)body.add("images",resource(f));return ai().post().uri("/recognize").contentType(MediaType.MULTIPART_FORM_DATA).body(body).retrieve().body(Map.class);}
 @GetMapping(value="/reports.csv",produces="text/csv") Object report(Authentication a){var rows=admin(a)?db.queryForList("select c.name,a.roll,a.student_name,count(*) total,count(*) filter(where a.state='PRESENT') present from attendance a join sessions s on s.id=a.session_id join courses c on c.id=s.course_id where s.status='FINALIZED' group by c.name,a.roll,a.student_name"):db.queryForList("select c.name,a.roll,a.student_name,count(*) total,count(*) filter(where a.state='PRESENT') present from attendance a join sessions s on s.id=a.session_id join courses c on c.id=s.course_id where s.status='FINALIZED' and c.teacher=? group by c.name,a.roll,a.student_name",a.getName());var out=new StringBuilder("Course,Roll,Name,Finalized sessions,Present,Percentage\n");for(var row:rows){for(String k:List.of("name","roll","student_name","total","present"))out.append(csv(row.get(k))).append(',');out.append(100.0*((Number)row.get("present")).doubleValue()/((Number)row.get("total")).doubleValue()).append('\n');}return out.toString();}
 String csv(Object x){String v=String.valueOf(x);if(v.matches("^[=+@-].*"))v="'"+v;return "\""+v.replace("\"","\"\"")+"\"";}
 ByteArrayResource resource(MultipartFile f)throws Exception{check(f.getSize()>0&&f.getSize()<=10485760,"Invalid image size");return new ByteArrayResource(f.getBytes()){@Override public String getFilename(){return "upload.jpg";}};}
 RestClient ai(){return RestClient.builder().baseUrl(System.getenv().getOrDefault("AI_URL","http://localhost:8001")).defaultHeader("X-Service-Key",System.getenv("AI_SERVICE_KEY")).build();}
}
